/**
 * Deterministic indicator kernels ported from apps-gitops
 * `apps/user/cognitive-risk/signal-edge/src/{trend,volume}_engine.py` (ADR-0005).
 *
 * Each kernel reproduces pandas_ta_classic 0.9.0 (the library those engines call) and is
 * checked against fixtures generated by that library (tools/parity/signal_fixtures.py).
 * Series use NaN for "no value", as pandas does; outputs report null instead of NaN.
 */

export interface Candle { open_time: number; o: number; h: number; l: number; c: number; v: number }

export const IMPLEMENTATION = "signal-engine/1 (pandas_ta_classic 0.9.0 parity)";

const nan = (n: number) => new Array<number>(n).fill(NaN);
const finite = Number.isFinite;

function rollingSum(x: number[], n: number): number[] {
  const out = nan(x.length);
  for (let i = n - 1; i < x.length; i++) {
    let s = 0;
    let ok = true;
    for (let j = i - n + 1; j <= i; j++) {
      if (!finite(x[j])) { ok = false; break; }
      s += x[j];
    }
    if (ok) out[i] = s;
  }
  return out;
}

export function sma(x: number[], n: number): number[] {
  if (x.length < n) return nan(x.length);
  return rollingSum(x, n).map((s) => s / n);
}

/** pandas ewm(adjust=False) over a series whose first value is a seed at index `seedAt`. */
function ewmFromSeed(x: number[], seedAt: number, seed: number, alpha: number): number[] {
  const out = nan(x.length);
  let prev = seed;
  out[seedAt] = seed;
  for (let i = seedAt + 1; i < x.length; i++) {
    if (!finite(x[i])) { out[i] = NaN; continue; } // ignore_na=False: state carries, output masked
    prev = alpha * x[i] + (1 - alpha) * prev;
    out[i] = prev;
  }
  return out;
}

function firstFinite(x: number[]): number {
  return x.findIndex((v) => finite(v));
}

function smaSeeded(x: number[], n: number, alpha: number): number[] {
  const fv = firstFinite(x);
  if (fv < 0 || fv + n > x.length) return nan(x.length);
  let s = 0;
  for (let i = fv; i < fv + n; i++) s += x[i];
  return ewmFromSeed(x, fv + n - 1, s / n, alpha);
}

/** EMA seeded with the SMA of the first `n` values (pandas_ta default `sma=True`). */
export function ema(x: number[], n: number): number[] {
  if (x.length < n) return nan(x.length);
  return smaSeeded(x, n, 2 / (n + 1));
}

/** Wilder's moving average (pandas_ta `rma`). */
export function rma(x: number[], n: number): number[] {
  if (x.length < n) return nan(x.length);
  return smaSeeded(x, n, 1 / n);
}

export function trueRange(h: number[], l: number[], c: number[]): number[] {
  return h.map((hi, i) => (i === 0 ? NaN : Math.max(Math.abs(hi - l[i]), Math.abs(hi - c[i - 1]), Math.abs(c[i - 1] - l[i]))));
}

export function atr(h: number[], l: number[], c: number[], n: number): number[] {
  if (c.length < n) return nan(c.length);
  return rma(trueRange(h, l, c), n);
}

/** TA-Lib-exact Wilder cumulative smoothing (pandas_ta `wilder_smooth`). */
function wilderSmooth(raw: number[], n: number): number[] {
  const len = raw.length;
  const fv = firstFinite(raw);
  const start = fv < 0 ? len : Math.max(fv, 1);
  const out = nan(len);
  if (start + n - 1 > len) return out;
  let value = 0;
  for (let i = start; i < start + n - 1; i++) if (finite(raw[i])) value += raw[i];
  out[start + n - 2] = value;
  for (let i = start + n - 1; i < len; i++) {
    if (finite(raw[i])) value = value - value / n + raw[i];
    out[i] = value;
  }
  for (let i = start; i < len; i++) if (!finite(raw[i])) out[i] = NaN;
  return out;
}

const EPSILON = 2.220446049250313e-16;

export function adx(h: number[], l: number[], c: number[], n: number): { adx: number[]; dmp: number[]; dmn: number[] } {
  const len = c.length;
  if (len < n) return { adx: nan(len), dmp: nan(len), dmn: nan(len) };
  const pos = nan(len);
  const neg = nan(len);
  for (let i = 1; i < len; i++) {
    const up = h[i] - h[i - 1];
    const dn = l[i - 1] - l[i];
    const p = up > dn && up > 0 ? up : 0;
    const q = dn > up && dn > 0 ? dn : 0;
    pos[i] = Math.abs(p) < EPSILON ? 0 : p;
    neg[i] = Math.abs(q) < EPSILON ? 0 : q;
  }
  const trS = wilderSmooth(trueRange(h, l, c), n);
  const posS = wilderSmooth(pos, n);
  const negS = wilderSmooth(neg, n);
  const dmp = trS.map((t, i) => (t === 0 ? 0 : (100 * posS[i]) / t));
  const dmn = trS.map((t, i) => (t === 0 ? 0 : (100 * negS[i]) / t));
  const seed = firstFinite(trS);
  if (seed >= 0) { dmp[seed] = NaN; dmn[seed] = NaN; }
  const dx = dmp.map((p, i) => {
    const d = p + dmn[i];
    return d === 0 ? 0 : (100 * Math.abs(p - dmn[i])) / d;
  });
  return { adx: rma(dx, n), dmp, dmn };
}

export function supertrend(h: number[], l: number[], c: number[], n: number, mult: number): { trend: number[]; direction: number[] } {
  const len = c.length;
  const trend = nan(len);
  const direction = nan(len);
  if (len < n) return { trend, direction };
  const a = atr(h, l, c, n);
  const ub = h.map((hi, i) => (hi + l[i]) / 2 + mult * a[i]);
  const lb = h.map((hi, i) => (hi + l[i]) / 2 - mult * a[i]);
  const fub = nan(len);
  const flb = nan(len);
  for (let i = 1; i < len; i++) {
    let dir: number;
    if (!finite(fub[i - 1]) || !finite(flb[i - 1])) {
      fub[i] = ub[i];
      flb[i] = lb[i];
      dir = 1;
    } else {
      fub[i] = ub[i] < fub[i - 1] || c[i - 1] > fub[i - 1] ? ub[i] : fub[i - 1];
      flb[i] = lb[i] > flb[i - 1] || c[i - 1] < flb[i - 1] ? lb[i] : flb[i - 1];
      dir = c[i] > fub[i - 1] ? 1 : c[i] < flb[i - 1] ? -1 : direction[i - 1];
    }
    if (!finite(fub[i]) || !finite(flb[i])) continue;
    direction[i] = dir;
    trend[i] = dir > 0 ? flb[i] : fub[i];
  }
  return { trend, direction };
}

function midprice(h: number[], l: number[], n: number): number[] {
  const out = nan(h.length);
  for (let i = n - 1; i < h.length; i++) {
    let hi = -Infinity;
    let lo = Infinity;
    for (let j = i - n + 1; j <= i; j++) { hi = Math.max(hi, h[j]); lo = Math.min(lo, l[j]); }
    out[i] = 0.5 * (lo + hi);
  }
  return out;
}

/** Last-row Ichimoku values as pandas_ta reports them (spans shifted forward by kijun). */
export function ichimokuLast(h: number[], l: number[], tenkan = 9, kijun = 26, senkou = 52) {
  const len = h.length;
  if (len < Math.max(tenkan, kijun, senkou)) return null;
  const t = midprice(h, l, tenkan);
  const k = midprice(h, l, kijun);
  const b = midprice(h, l, senkou);
  const at = len - 1 - kijun;
  return {
    tenkan: t[len - 1],
    kijun: k[len - 1],
    span_a: at >= 0 ? 0.5 * (t[at] + k[at]) : NaN,
    span_b: at >= 0 ? b[at] : NaN,
  };
}

export function obv(c: number[], v: number[]): number[] {
  let total = 0;
  return c.map((ci, i) => {
    const sign = i === 0 ? 1 : ci > c[i - 1] ? 1 : ci < c[i - 1] ? -1 : 0;
    total += sign * v[i];
    return total;
  });
}

export function mfi(h: number[], l: number[], c: number[], v: number[], n: number): number[] {
  const len = c.length;
  if (len < n) return nan(len);
  const tp = c.map((ci, i) => (h[i] + l[i] + ci) / 3);
  const pos = nan(len);
  const neg = nan(len);
  for (let i = 1; i < len; i++) {
    const flow = tp[i] * v[i];
    const change = tp[i] - tp[i - 1];
    pos[i] = change > 0 ? flow : 0;
    neg[i] = change < 0 ? flow : 0;
  }
  const ps = rollingSum(pos, n);
  const ns = rollingSum(neg, n);
  return ps.map((p, i) => {
    const d = p + ns[i];
    return d === 0 ? 0 : (100 * p) / d;
  });
}

export function cmf(h: number[], l: number[], c: number[], v: number[], n: number): number[] {
  const len = c.length;
  if (len < n) return nan(len);
  const ad = c.map((ci, i) => {
    const range = h[i] - l[i];
    return range === 0 ? 0 : (2 * ci - (h[i] + l[i])) * (v[i] / range);
  });
  const adSum = rollingSum(ad, n);
  const vSum = rollingSum(v, n);
  return adSum.map((s, i) => s / vSum[i]);
}

/** Python's round(x, digits) for finite values; null for NaN/undefined. */
export function round(x: number | undefined, digits: number): number | null {
  if (x === undefined || !finite(x)) return null;
  return Number(x.toFixed(digits));
}

const last = (x: number[]) => x[x.length - 1];

/** trend_engine._compute: EMA 9/21/50/200, SMA 20/50/200, ADX(14), Supertrend(10, 3), Ichimoku. */
export function trendIndicators(candles: Candle[]): Record<string, number | null> {
  const c = candles.map((k) => k.c);
  const h = candles.map((k) => k.h);
  const l = candles.map((k) => k.l);
  const out: Record<string, number | null> = {};
  for (const p of [9, 21, 50, 200]) out[`ema_${p}`] = round(last(ema(c, p)), 6);
  for (const p of [20, 50, 200]) out[`sma_${p}`] = round(last(sma(c, p)), 6);
  const a = adx(h, l, c, 14);
  out.adx = round(last(a.adx), 4);
  out.adx_plus_di = round(last(a.dmp), 4);
  out.adx_minus_di = round(last(a.dmn), 4);
  const st = supertrend(h, l, c, 10, 3);
  out.supertrend = round(last(st.trend), 6);
  const dir = last(st.direction);
  out.supertrend_direction = finite(dir) ? dir : null;
  const ich = ichimokuLast(h, l);
  out.ichimoku_tenkan = round(ich?.tenkan, 6);
  out.ichimoku_kijun = round(ich?.kijun, 6);
  out.ichimoku_span_a = round(ich?.span_a, 6);
  out.ichimoku_span_b = round(ich?.span_b, 6);
  return out;
}

/** volume_engine._compute: VWAP over the window, OBV, MFI(14), CMF(20). */
export function volumeIndicators(candles: Candle[]): Record<string, number | null> {
  const c = candles.map((k) => k.c);
  const h = candles.map((k) => k.h);
  const l = candles.map((k) => k.l);
  const v = candles.map((k) => k.v);
  let pv = 0;
  let vol = 0;
  candles.forEach((k) => { pv += ((k.h + k.l + k.c) / 3) * k.v; vol += k.v; });
  return {
    vwap: round(vol === 0 ? NaN : pv / vol, 6),
    obv: round(last(obv(c, v)), 2),
    mfi_14: round(last(mfi(h, l, c, v, 14)), 4),
    cmf_20: round(last(cmf(h, l, c, v, 20)), 6),
  };
}

/** Minimum history before an engine publishes, as in the Python services. */
export const MIN_HISTORY = { trend: 20, volume: 21 } as const;
export const WINDOW = 210;
